    .normalize("NFD")
    .replace(/\p{Diacritic}/gu, "")
    .toLowerCase()
    .replace(/[\u0027\u0022\u2018\u2019\u201c\u201d]/gu, "")
    .replace(/\p{P}/gu, " ")
    .replace(/\s+/gu, " ")
    .trim();
